{
  "schemaVersion": 1,
  "id": "ai-product-landing",
  "version": "1.0.0",
  "kind": "template",
  "name": "Ai Product Landing",
  "description": "An intelligent canvas that turns your team's knowledge into useful, dependable workflows.",
  "tags": ["marketing", "terminal", "synapse"],
  "files": ["registry/templates/ai-product-landing.json", "lib/template-renderer.tsx"],
  "dependencies": [
    "class-variance-authority",
    "clsx",
    "lucide-react",
    "motion",
    "radix-ui",
    "react",
    "tailwind-merge",
    "zod"
  ],
  "category": "marketing",
  "defaultStyleId": "gradient-tech",
  "defaultThemeId": "violet",
  "defaultMotionId": "premium-smooth",
  "defaultMode": "dark",
  "compatibleStyles": [
    "modern-minimal",
    "corporate-enterprise",
    "glassmorphism",
    "neo-brutalism",
    "luxury-premium",
    "editorial-magazine",
    "swiss-grid",
    "soft-ui",
    "dark-cinematic",
    "cyberpunk",
    "retro-arcade",
    "playful-friendly",
    "organic-natural",
    "gradient-tech",
    "monochrome",
    "bento-modern",
    "industrial",
    "warm-human",
    "futuristic-spatial",
    "creative-expressive"
  ],
  "supportedThemes": [
    "ocean-blue",
    "royal-purple",
    "emerald",
    "sunset-orange",
    "ruby-red",
    "rose",
    "violet",
    "midnight",
    "slate-neutral",
    "warm-sand",
    "forest",
    "teal",
    "indigo",
    "sky",
    "lavender",
    "citrus",
    "coral",
    "coffee",
    "luxury-gold",
    "monochrome-dark",
    "aurora",
    "cyberpunk-neon",
    "pastel",
    "enterprise-neutral"
  ],
  "supportedMotion": [
    "no-motion",
    "subtle",
    "premium-smooth",
    "spring-interactive",
    "energetic",
    "editorial",
    "stagger-reveal",
    "fade-reveal",
    "slide-reveal",
    "scale-reveal",
    "parallax-light",
    "cinematic",
    "futuristic",
    "playful",
    "dashboard-fast",
    "luxury-slow"
  ],
  "components": ["ui-button", "ui-card"],
  "sections": [
    {
      "id": "navbar-floating",
      "key": "navbar-floating",
      "content": {
        "eyebrow": "Navbar",
        "title": "Synapse",
        "href": "#features-tabs",
        "items": [
          {
            "title": "A clear starting point",
            "description": "Everything you need, thoughtfully organized."
          },
          {
            "title": "Built around your day",
            "description": "Flexible tools that adapt to the way you work."
          },
          {
            "title": "Room to grow",
            "description": "Start simply. Add more when you need it."
          },
          {
            "title": "People first",
            "description": "Accessible, intuitive experiences for everyone."
          }
        ]
      }
    },
    {
      "id": "hero-terminal",
      "key": "hero-terminal",
      "content": {
        "eyebrow": "Synapse",
        "title": "From possibility to production.",
        "description": "An intelligent canvas that turns your team's knowledge into useful, dependable workflows.",
        "action": "Explore Synapse",
        "href": "#features-tabs",
        "items": [
          {
            "title": "A clear starting point",
            "description": "Everything you need, thoughtfully organized."
          },
          {
            "title": "Built around your day",
            "description": "Flexible tools that adapt to the way you work."
          },
          {
            "title": "Room to grow",
            "description": "Start simply. Add more when you need it."
          },
          {
            "title": "People first",
            "description": "Accessible, intuitive experiences for everyone."
          }
        ]
      }
    },
    {
      "id": "features-tabs",
      "key": "features-tabs",
      "content": {
        "eyebrow": "Features",
        "title": "Everything you need. Nothing in your way.",
        "href": "#features-tabs",
        "items": [
          {
            "title": "Connect your knowledge",
            "description": "Organize documents and ideas into a searchable working context."
          },
          {
            "title": "Design a useful workflow",
            "description": "Combine prompts, review steps, and reusable outputs on one canvas."
          },
          {
            "title": "Keep people in the loop",
            "description": "Review suggestions and approve important changes before they ship."
          },
          {
            "title": "Understand every result",
            "description": "Inspect source context and refine your workflow with clear feedback."
          }
        ]
      }
    },
    {
      "id": "content-showcase",
      "key": "content-showcase",
      "content": {
        "eyebrow": "Showcase",
        "title": "A closer look",
        "href": "#features-tabs",
        "items": [
          {
            "title": "A clear starting point",
            "description": "Everything you need, thoughtfully organized."
          },
          {
            "title": "Built around your day",
            "description": "Flexible tools that adapt to the way you work."
          },
          {
            "title": "Room to grow",
            "description": "Start simply. Add more when you need it."
          },
          {
            "title": "People first",
            "description": "Accessible, intuitive experiences for everyone."
          }
        ]
      }
    },
    {
      "id": "content-metrics",
      "key": "content-metrics",
      "content": {
        "eyebrow": "Metrics",
        "title": "A little progress, every day",
        "href": "#features-tabs",
        "items": [
          {
            "title": "Active members",
            "description": "12,480",
            "value": "12,480"
          },
          {
            "title": "Satisfaction",
            "description": "98%",
            "value": "98%"
          },
          {
            "title": "Years of experience",
            "description": "12",
            "value": "12"
          },
          {
            "title": "Community projects",
            "description": "240",
            "value": "240"
          }
        ]
      }
    },
    {
      "id": "pricing-usage",
      "key": "pricing-usage",
      "content": {
        "eyebrow": "Pricing",
        "title": "Choose what works for you",
        "href": "#features-tabs",
        "items": [
          {
            "title": "Starter",
            "description": "For individuals getting started"
          },
          {
            "title": "Team",
            "description": "For growing teams doing more"
          },
          {
            "title": "Scale",
            "description": "For organizations with bigger ambitions"
          }
        ]
      }
    },
    {
      "id": "faq-stack",
      "key": "faq-stack",
      "content": {
        "eyebrow": "Faq",
        "title": "A few things you might be wondering",
        "href": "#features-tabs",
        "items": [
          {
            "title": "How do I get started?",
            "description": "Choose the option that suits you and follow the guided steps. You can explore the demo before making a decision."
          },
          {
            "title": "Can I change my selection later?",
            "description": "Yes. Your needs can change, and the experience is designed to grow with you."
          },
          {
            "title": "Is support available?",
            "description": "The sample support form demonstrates the flow locally. Connect your own support service for production."
          },
          {
            "title": "What is included?",
            "description": "All listed features are included in the selected option. Review the comparison for details."
          }
        ]
      }
    },
    {
      "id": "content-contact",
      "key": "content-contact",
      "content": {
        "eyebrow": "LET’S CONNECT",
        "title": "Start a conversation.",
        "description": "Tell us a little about what you have in mind.",
        "items": []
      }
    },
    {
      "id": "footer-minimal",
      "key": "footer-minimal",
      "content": {
        "eyebrow": "Footer",
        "title": "Synapse",
        "href": "#features-tabs",
        "items": [
          {
            "title": "A clear starting point",
            "description": "Everything you need, thoughtfully organized."
          },
          {
            "title": "Built around your day",
            "description": "Flexible tools that adapt to the way you work."
          },
          {
            "title": "Room to grow",
            "description": "Start simply. Add more when you need it."
          },
          {
            "title": "People first",
            "description": "Accessible, intuitive experiences for everyone."
          }
        ]
      }
    }
  ],
  "responsive": true,
  "accessible": true
}
